sys_ws_operation.operation_script:
(function process( /*RESTAPIRequest*/ request, /*RESTAPIResponse*/ response) {

    //get search parameters

    var object_id_type = request.body.data.object_id_type;
    var object_id = request.body.data.object_id;
    var user_id = request.body.data.user_id + "@hsbc.com";
    // var user_id = request.body.data.user_id;
    var queue_name = request.body.data.queue_name;
    var auth = false;

    //find user_id

    gs.info('before auth', 'unstructure instructions');

    auth = new x_hsb11_mss_unst_0.MSS_Unstructured_Instruction_Utils().getUserAuthDetail(user_id, queue_name);
    gs.info('before auth ' + auth, 'unstructure instructions');

    if (auth == true || auth == false) {
        //return response
        var result = {
            "authorized": auth
        };

        response.setContentType('application/json');
        response.setStatus(200);
    } else {
        response.setStatus(403);
        response.setBody({
            error: 'User ID Not Found'
        });
        return;
    }
    response.setBody(result);



})(request, response);
